// Config. HUB_ID is Fairbank's HubSpot account (the id in the app's
// HubSpot record links). RETURN_ORIGINS are the only sites a session
// token is ever sent back to. Remove the localhost entries once local
// testing is done.
const CONFIG = {
  HUB_ID: '43793456',
  REDIRECT_URI: 'https://n8n.fairbankequipment.com/webhook/e-order-placement/auth/hubspot',
  SESSION_HOURS: 12,
  DEFAULT_RETURN: 'https://sales.fairbankequipment.com/',
  RETURN_ORIGINS: [
    'https://sales.fairbankequipment.com',
    'https://profitpad-inc.github.io',
  ],
  RETURN_LOCAL: /^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/,
};

const q = $input.first().json.query || {};

// state = base64url(JSON { r: return URL, n: nonce }), made by auth.js.
// Plain JS on purpose: Buffer and URL are not available in this n8n's
// Code sandbox (a first version using them rejected every state).
function b64urlToText(s) {
  const abc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  let bits = 0, acc = 0, out = '';
  for (const ch of String(s)) {
    const v = abc.indexOf(ch);
    if (v < 0) throw new Error('bad state');
    acc = (acc << 6) | v; bits += 6;
    if (bits >= 8) {
      bits -= 8;
      const b = (acc >> bits) & 255;
      if (b > 127) throw new Error('bad state'); // auth.js only sends ASCII
      out += String.fromCharCode(b);
    }
  }
  return out;
}
let returnUrl = CONFIG.DEFAULT_RETURN;
let nonce = '';
try {
  const s = JSON.parse(b64urlToText(q.state || ''));
  const r = String(s.r || '').split('#')[0];
  const m = r.match(/^(https?:\/\/[^\/?#\\]+)(?:[\/?]|$)/i);
  const origin = m ? m[1].toLowerCase() : '';
  if (origin && (CONFIG.RETURN_ORIGINS.includes(origin) || CONFIG.RETURN_LOCAL.test(origin))) {
    returnUrl = r;
  }
  nonce = String(s.n || '').replace(/[^A-Za-z0-9]/g, '').slice(0, 64);
} catch (e) { /* bad state: fall back to the default page, no nonce */ }

const fail = (msg) => [{ json: { ok: false,
  redirect: returnUrl + '#fb_auth_error=' + encodeURIComponent(msg) } }];

if (q.error) return fail('HubSpot sign-in was cancelled or refused (' + String(q.error) + ').');
if (!nonce) return fail('Sign-in link was invalid. Try again.');
const code = String(q.code || '').trim();
if (!code) return fail('HubSpot did not return a sign-in code. Try again.');

return [{ json: { ok: true, code, returnUrl, nonce, ...CONFIG } }];

const cfg = $('Validate').first().json;
const r = $input.first().json;
const fail = (msg) => [{ json: { ok: false,
  redirect: cfg.returnUrl + '#fb_auth_error=' + encodeURIComponent(msg) } }];
if (r.error || !r.access_token) {
  return fail('HubSpot sign-in failed at the token step. Try again.');
}
return [{ json: { ok: true, access_token: r.access_token } }];

const cfg = $('Validate').first().json;
const r = $input.first().json;
const fail = (msg) => [{ json: { ok: false,
  redirect: cfg.returnUrl + '#fb_auth_error=' + encodeURIComponent(msg) } }];
if (r.error) return fail('HubSpot sign-in failed at the identity step. Try again.');
// The proof: HubSpot itself says which account and user the token is for.
if (String(r.hub_id || '') !== cfg.HUB_ID) {
  return fail('That HubSpot login is not in the Fairbank account.');
}
const hsUserId = String(r.user_id || '');
const email = String(r.user || '').trim().toLowerCase();
if (!hsUserId && !email) return fail('HubSpot did not say who signed in. Try again.');
const userProps = [
  'e_user_id', 'e_default_branch', 'e_territory', 'hs_internal_user_id',
  'hs_given_name', 'hs_family_name', 'hs_email', 'hs_searchable_calculated_name',
];
const groups = [];
if (hsUserId) groups.push({ filters: [{ propertyName: 'hs_internal_user_id', operator: 'EQ', value: hsUserId }] });
if (email) groups.push({ filters: [{ propertyName: 'hs_email', operator: 'EQ', value: email }] });
return [{ json: { ok: true, hsUserId, email, userProps, filter: { filterGroups: groups } } }];

// Same property names as the user-lookup flow. Branch and territory
// names are UNVERIFIED placeholders there too.
const PROPS = { idProp: 'e_user_id', branchProp: 'e_default_branch', territoryProp: 'e_territory' };
const cfg = $('Validate').first().json;
const who = $('Check identity').first().json;
const r = $input.first().json;
const fail = (msg) => [{ json: { ok: false,
  redirect: cfg.returnUrl + '#fb_auth_error=' + encodeURIComponent(msg) } }];
if (r.error) return fail('HubSpot user lookup failed. Try again.');
const results = Array.isArray(r.results) ? r.results : (r.id ? [r] : []);
// Prefer the record whose user id matches; the email match is a fallback.
const u = results.find(x => String((x.properties || {}).hs_internal_user_id || '') === who.hsUserId)
  || results.find(x => String((x.properties || {}).hs_email || '').toLowerCase() === who.email);
if (!u) return fail('Your HubSpot user was not found in the Fairbank account.');
const p = u.properties || {};
const eUserId = String(p[PROPS.idProp] || '').trim().toUpperCase();
if (!eUserId) {
  return fail('Your HubSpot user has no Eclipse user ID (e_user_id). Ask an admin to add it.');
}
const now = Math.floor(Date.now() / 1000);
const name = [p.hs_given_name, p.hs_family_name].filter(Boolean).join(' ') || p.hs_searchable_calculated_name || '';
return [{ json: { ok: true, claims: {
  iss: 'fairbank-sales',
  sub: who.hsUserId || String(u.id || ''),
  iat: now,
  exp: now + cfg.SESSION_HOURS * 3600,
  hub_id: cfg.HUB_ID,
  e_user_id: eUserId,
  name,
  email: p.hs_email || who.email,
  default_branch: p[PROPS.branchProp] || '',
  territory: p[PROPS.territoryProp] || '',
  hs_user_id: String(u.id || ''),
  hs_owner_id: String((u.owner && u.owner.id) || ''),
} } }];

const cfg = $('Validate').first().json;
const token = $input.first().json.token;
if (!token) {
  return [{ json: { redirect: cfg.returnUrl + '#fb_auth_error=' + encodeURIComponent('Could not create a session. Try again.') } }];
}
// In the fragment, so the token never reaches a server log.
return [{ json: { redirect: cfg.returnUrl + '#fb_session=' + encodeURIComponent(token)
  + '&fb_nonce=' + encodeURIComponent(cfg.nonce) } }];
